-- KO-225 group 2 missing body_id translation batch 5

update public.content_variants set body = $json${"text":"Bayu lost his job and was unable to pay his mortgage installments. He immediately contacted the bank to explain the situation. The bank offers an option to defer installments for three months. Because he didn't ignore the problem, his credit record remained intact and he had time to look for a new job."}$json$::jsonb, body_id = $json${"text":"Bayu kehilangan pekerjaan dan tidak bisa membayar cicilan KPR. Ia segera menghubungi bank untuk menjelaskan situasinya. Bank menawarkan opsi penangguhan cicilan selama tiga bulan. Karena ia tidak mengabaikan masalah, rekam kreditnya tetap terjaga dan ia punya waktu mencari pekerjaan baru."}$json$::jsonb where id = '65d1de19-81b3-4933-96a3-11070c1fc002';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"KUR loans for small businesses that generate profits","options":["KUR loans for small businesses that generate profits","PayLater to buy hoodies","0% installments for holidays to Bali","Pinjol to buy the latest smartphone"],"question":"Which is an example of good debt?","difficulty":"beginner","explanation":"KUR for profitable businesses can increase income, so it is considered good debt."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Pinjaman KUR untuk usaha kecil yang menghasilkan laba","options":["Pinjaman KUR untuk usaha kecil yang menghasilkan laba","PayLater untuk membeli hoodie","Cicilan 0% untuk liburan ke Bali","Pinjol untuk beli smartphone terbaru"],"question":"Manakah contoh utang baik?","difficulty":"beginner","explanation":"KUR untuk usaha yang menguntungkan bisa meningkatkan pendapatan, jadi termasuk utang baik."}$json$::jsonb where id = '65d782de-d4c7-4373-8048-37cc2ca849ad';
update public.content_variants set body = $json${"text":"A boarding house entrepreneur borrows from the bank to buy a second rental property. The tenant pays the installments and leaves a profit. That's good debt. A student uses PayLater to buy branded shoes that are not really needed. That's bad debt because it only adds to your monthly burden."}$json$::jsonb, body_id = $json${"text":"Seorang pengusaha kos meminjam dari bank untuk membeli properti kedua yang disewakan. Penyewa membayar cicilan dan menyisakan laba. Itu utang baik. Seorang mahasiswa memakai PayLater untuk membeli sepatu branded yang tidak benar-benar dibutuhkan. Itu utang buruk karena hanya menambah beban bulanan."}$json$::jsonb where id = '6668212d-e622-4b74-8f5f-f842b83b4237';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Crypto prices are very stable like bank savings.","difficulty":"beginner","explanation":"Crypto is very volatile. The price can rise or fall drastically in a matter of hours or days."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Harga kripto sangat stabil seperti tabungan bank.","difficulty":"beginner","explanation":"Kripto sangat volatil. Harganya bisa naik atau turun drastis dalam hitungan jam atau hari."}$json$::jsonb where id = '666921be-6a51-4d76-9b6b-bbd820f27e4d';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"High risk digital assets","options":["High risk digital assets","Safe deposits such as savings","Wealth guarantee from the government","Shares in central banks"],"question":"Owning crypto means owning...","difficulty":"beginner","explanation":"Crypto is a digital asset whose price is very volatile and is not guaranteed by LPS or the government."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Aset digital berisiko tinggi","options":["Aset digital berisiko tinggi","Simpanan aman seperti tabungan","Jaminan kekayaan dari pemerintah","Saham di bank sentral"],"question":"Memiliki kripto berarti memiliki...","difficulty":"beginner","explanation":"Kripto adalah aset digital yang harganya sangat fluktuatif dan tidak dijamin oleh LPS atau pemerintah."}$json$::jsonb where id = '673265a2-f1b1-412f-90b4-75dfabc180fb';
update public.content_variants set body = $json${"text":"Andi bought shoes for IDR 500,000 using PayLater because he was interested in the cashback promo. He forgot to pay the bill and was fined IDR 100,000. In the end, shoes that were supposed to cost Rp. 500,000 ended up costing Rp. 600,000, exceeding his budget."}$json$::jsonb, body_id = $json${"text":"Andi membeli sepatu Rp 500.000 pakai PayLater karena tertarik dengan promo cashback. Ia lupa membayar tagihan dan kena denda Rp 100.000. Akhirnya sepatu yang seharusnya Rp 500.000 malah jadi Rp 600.000, melebihi anggaran yang ia miliki."}$json$::jsonb where id = '6e48e700-2f59-4873-829a-5a1eac00a4aa';
update public.content_variants set body = $json${"type":"fill_blank","answer":"plan","question":"Creating written _____ helps turn debt panic into measurable progress.","difficulty":"beginner","explanation":"A repayment plan provides direction, deadlines, and motivation when managing a lot of debt."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"rencana","question":"Membuat _____ tertulis membantu mengubah panik utang menjadi kemajuan yang terukur.","difficulty":"beginner","explanation":"Rencana pelunasan memberikan arah, tenggat waktu, dan motivasi saat mengelola banyak utang."}$json$::jsonb where id = '6ed412fd-1dbf-484d-9570-3d57d53abbcd';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Maximum interest, minimum age, and consumer protection","options":["Maximum interest, minimum age, and consumer protection","Price of goods that can be purchased","Cashback reward amount","The name of the bank that can issue the card"],"question":"What does Bank Indonesia regulate regarding credit cards?","difficulty":"beginner","explanation":"PBI 14/2/2012 regulates interest rates, holder requirements, ceilings and consumer protection for credit cards."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Bunga maksimum, usia minimum, dan perlindungan konsumen","options":["Bunga maksimum, usia minimum, dan perlindungan konsumen","Harga barang yang boleh dibeli","Jumlah reward cashback","Nama bank yang boleh menerbitkan kartu"],"question":"Apa yang diatur Bank Indonesia terkait kartu kredit?","difficulty":"beginner","explanation":"PBI 14/2/2012 mengatur suku bunga, persyaratan pemegang, plafon, dan perlindungan konsumen kartu kredit."}$json$::jsonb where id = '7040fa6c-5a8a-45fb-86f1-04d09ebc6c5f';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"IDR 2 billion","options":["IDR 100 million","IDR 500 million","IDR 2 billion","Without limit"],"question":"What is the LPS guarantee limit per customer per bank?","difficulty":"beginner","explanation":"LPS (Deposit Insurance Agency) guarantees deposits of up to IDR 2 billion per customer per bank. This applies to savings, deposits and current accounts."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Rp 2 miliar","options":["Rp 100 juta","Rp 500 juta","Rp 2 miliar","Tanpa batas"],"question":"Berapa batas penjaminan LPS per nasabah per bank?","difficulty":"beginner","explanation":"LPS (Lembaga Penjamin Simpanan) menjamin simpanan hingga Rp 2 miliar per nasabah per bank. Ini berlaku untuk tabungan, deposito, dan giro."}$json$::jsonb where id = '7058e726-6227-451c-bb42-7255c0c1b2e3';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Credit card limits are additional income that can be spent freely.","difficulty":"beginner","explanation":"The credit card limit is a loan from the bank that must be repaid, not income."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Limit kartu kredit adalah penghasilan tambahan yang bisa dibelanjakan bebas.","difficulty":"beginner","explanation":"Limit kartu kredit adalah pinjaman dari bank yang harus dilunasi, bukan penghasilan."}$json$::jsonb where id = '712bc175-8241-411b-8269-de2e848b8adf';

